import os
import requests

def safety_threshold(payload, config=None):
    config = config or {}
    endpoint = "https://api.meaningcloud.com/sentiment-2.1"
    api_key = os.getenv("MEANINGCLOUD_API_KEY")
    params = {
        "key": api_key,
        "txt": payload,
        "lang": "en",
        "model": "general"
    }
    response = requests.get(endpoint, params=params)
    result = response.json()
    if result["status"]["code"] == "0":
        sentiment_score = result["score_tag"]
        thresholds = config.get("thresholds", {"positive": 0.6, "neutral": 0.4, "negative": 0.3})
        if sentiment_score.startswith("P") and float(sentiment_score[1:]) / 10 > thresholds["positive"]:
            return "positive"
        elif sentiment_score.startswith("N") and float(sentiment_score[1:]) / 10 > thresholds["negative"]:
            return "negative"
        else:
            return "neutral"
    else:
        raise Exception("API call failed")
